function normalizeWebsite(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  return /^https?:\/\//i.test(raw) ? raw.replace(/\/$/, '') : 'https://' + raw.replace(/\/$/, '');
}

function slugify(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .replace(/-{2,}/g, '-');
}

function hostSlugFromWebsite(website) {
  try {
    const host = new URL(website).hostname.replace(/^www\./i, '').toLowerCase();
    const parts = host.split('.').filter(Boolean);
    const ignored = new Set(['www', 'com', 'net', 'org', 'cn', 'io', 'app', 'vip', 'xyz', 'shop', 'site', 'cdn', 'm', 'vpn']);
    const preferred = parts.find((part) => !ignored.has(part)) || parts[0] || '';
    return slugify(preferred);
  } catch (error) {
    return '';
  }
}

function competitorSlug(providerName, website) {
  const fromName = slugify(providerName)
    .replace(/(^|-)vpn($|-)/g, '$1vpn$2')
    .replace(/^-+|-+$/g, '');
  if (fromName && fromName !== 'vpn' && fromName !== 'free-vpn') return fromName;
  return hostSlugFromWebsite(website) || fromName || 'vpn-provider';
}

function hashString(value) {
  return String(value || '').split('').reduce((hash, char) => {
    return ((hash << 5) - hash + char.charCodeAt(0)) >>> 0;
  }, 2166136261);
}

