  const slugCore = generatedSlugCore || expectedSlugCore;
  const slugHash = await shortSha([domain, slugCore, data.provider || data.competitor_name || '', data.run_seed || ''].join('|'));
  const slug = slugCore + '-' + slugHash;
  const title = data.title || '';
  const excerpt = data.excerpt || excerptFromContent(data.content);
  const publishedAt = data.publishedAt || now;
  const updatedAt = now;

  if (!domain) throw new Error('Cannot create GitHub file without domain.');
  if (!slugCore) throw new Error('Cannot create GitHub file without slug core.');

  const manifestEntry = {
    slug,
    title,
    excerpt,
    publishedAt,
    updatedAt,
  };

  const postPayload = {
    ...manifestEntry,
    contentHtml: contentToHtml(data.content),
  };

  output.push({
    json: {
      ...data,
      slug,
      slug_core: slugCore,
      slug_hash: slugHash,
      manifestEntry,
      githubFilePath: 'sites/' + domain + '/posts/' + slug + '.json',
