function decodeGithubContent(value) {
  return Buffer.from(String(value || '').replace(/\s/g, ''), 'base64').toString('utf8');
}

function parseManifest(value) {
  if (!value) return { items: [] };
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed.items) ? parsed : { items: [] };
  } catch (error) {
    return { items: [] };
  }
}

function cleanManifestEntry(entry) {
  return {
    slug: String(entry?.slug || '').trim(),
    title: String(entry?.title || ''),
    excerpt: String(entry?.excerpt || ''),
    publishedAt: String(entry?.publishedAt || ''),
    updatedAt: String(entry?.updatedAt || ''),
  };
}

function hasRequiredFields(entry) {
  return Boolean(entry.slug && entry.title && entry.excerpt && entry.publishedAt && entry.updatedAt);
}

